}

/// `order.json`: the sections and their stories, in order, and the
/// proposals still to be decided.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct Order {
    #[serde(default)]
    next: Vec<Entry>,
    #[serde(default)]
    backlog: Vec<Entry>,
    #[serde(default)]
