    story: String,
    at: usize,
    prompt: Entity<TextareaState>,
    _subscription: Subscription,
}

/// A step's row dragged among its story's steps.
#[derive(Clone)]
struct StepDrag {
    story: String,
    from: usize,
    label: SharedString,
}

impl Render for StepDrag {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
