    let theme = cx.theme();
    v_flex()
        .id(id)
        .w_full()
        .gap_1()
        .p_3()
        .rounded(px(4.))
        .border_1()
        .border_color(theme.border)
        .bg(theme.background)
}

/// A skeleton card, while the plan is read: a card's box, with muted bars
/// where its grip, mode pill, and title will be.
