    let theme = cx.theme();
    let muted = theme.muted;
    v_flex()
        .w_full()
        .gap_2()
        .p_3()
        .rounded(px(6.))
        .border_1()
        .border_color(theme.border)
        .bg(crate::theme::color(crate::theme::palette(cx).raised))
